		if (!textBuffer.trim()) {
			textBuffer = "";
			return null;
		}
		const entry = appendEntry({
			kind: "assistant",
			feeds: ["main"],
			text: textBuffer,
			meta: { messageRole: messageRole || "assistant" },
			blockId: `b${nextBlock++}`,
