					messageRole: messageRole || "assistant",
					charCount,
					collapsed: true,
					fullTextId: fullEntry.id,
				},
				blockId,
			});
		}
		return appendEntry({
			kind: "thinking",
			feeds: ["main", "thinking"],
			text: block,

