function handleToolStarted(event) {
	const flushed = flushOpenBlocks();
	const toolName = event.toolName || event.name || "tool";
	const toolCallId = event.toolCallId || event.id || null;
	const args = event.args || event.arguments || {};
	const entry = appendEntry({
		kind: "tool",
		feeds: ["main", "tools"],
		text: `[TOOL] ${toolName}(${summarizeToolStart(toolName, args, { maxLength: toolArgsMaxLength })})`,
		meta: { toolName, toolCallId, args, output: "", isError: false },
		tool: { callId: toolCallId, name: toolName, args },
		blockId: `b${nextBlock++}`,
	});
	openToolEntry = entry;
	toolStartMs.set(entry, Date.now());
	return [...flushed, entry];
}

function handleToolUpdated(event) {
	const partial = readToolPartial(event);
	if (!partial || !openToolEntry) return [];
	const outputCap = maxEntryBytes > 0 ? maxEntryBytes : 8192;
	const combined = openToolEntry.meta.output
		? `${openToolEntry.meta.output}\n${partial}`
		: partial;
	openToolEntry.meta.output = excerptText(combined, outputCap);
	if (openToolEntry.tool && typeof openToolEntry.tool === "object") {
		openToolEntry.tool = {
			...openToolEntry.tool,
			partials: openToolEntry.meta.output,
		};
	}
	return [];
}

function handleToolFinished(event) {
	const toolName =
		event.toolName || event.name || openToolEntry?.meta.toolName || "tool";
	const toolCallId =
		event.toolCallId || event.id || openToolEntry?.meta.toolCallId || null;
	const isError = Boolean(
		event.isError || event.error || event.result?.isError || event.result?.error,
	);
	const resultText = extractToolResultText(event);
	// Per-step timing: explicit harness timings win; otherwise the
	// measured wall-clock between tool_started and tool_finished, but
	// only for steps slow enough to matter (same-tick unit pairs stay
	// byte-identical). Stored on meta/tool always; rendered on [RESULT].
	const startedAt = openToolEntry ? toolStartMs.get(openToolEntry) : null;
	const measuredMs =
		typeof startedAt === "number" ? Date.now() - startedAt : null;
	const durationMs =
		explicitDurationMs(event) ??
		(typeof measuredMs === "number" && measuredMs >= MEASURED_TIMING_FLOOR_MS
			? measuredMs
			: null);
	const timingSuffix =
		typeof durationMs === "number" ? ` (${formatDurationMs(durationMs)})` : "";
	if (openToolEntry) {
		toolStartMs.delete(openToolEntry);
		openToolEntry.meta.isError = isError;
		// Keep the full output record (streamed partials + final result) on
		// the structured tools feed.
		if (resultText) {
			openToolEntry.meta.output = openToolEntry.meta.output
				? `${openToolEntry.meta.output}\n${resultText}`
				: resultText;
		}
		if (openToolEntry.tool && typeof openToolEntry.tool === "object") {
			openToolEntry.tool = {
				...openToolEntry.tool,
				result: resultText,
				partials: openToolEntry.meta.output,
				...(typeof durationMs === "number" ? { durationMs } : {}),
			};
		}
		if (typeof durationMs === "number") {
			openToolEntry.meta.durationMs = durationMs;
		}
	}
	// The [RESULT] excerpt mirrors today's behavior: the tool's FINAL result;
	// streamed partials only stand in when the result itself is empty.
	const fullOutput = resultText || openToolEntry?.meta.output || "";
	openToolEntry = null;

	const emitted = [];
	if (isError) {
		const errDetail = event.error || resultText || "Tool execution error";
		emitted.push(
			appendEntry({
				kind: "error",
				feeds: ["main"],
				text: `[ERROR] Tool ${toolName} failed: ${typeof errDetail === "string" ? errDetail : JSON.stringify(errDetail)}${timingSuffix}`,
				meta: {
					toolName,
					toolCallId,
					...(typeof durationMs === "number" ? { durationMs } : {}),
				},
			}),
		);
		return emitted;
	}
	const excerpt = summarizeToolResult(toolName, fullOutput.trim(), {
		maxLength: resultMaxLength,
	});
	if (excerpt) {
		emitted.push(
			appendEntry({
				kind: "tool",
				feeds: ["tools"],
				text: `[RESULT] ${excerpt}${timingSuffix}`,
				meta: {
					toolName,
					toolCallId,
					...(typeof durationMs === "number" ? { durationMs } : {}),
				},
				tool: {
					callId: toolCallId,
					name: toolName,
					result: resultText,
					...(typeof durationMs === "number" ? { durationMs } : {}),
				},
			}),
		);
	}
	return emitted;
}

const handleRunFinished = (event = {}) => {
	const flushed = flushOpenBlocks();
	const emitted = [...flushed];
	if (event.usage && typeof event.usage === "object") {
		const usageEntry = maybeEmitUsage(event.usage, event.model);
		if (usageEntry) emitted.push(usageEntry);
	}
	const line = formatRunDoneLine(event);
	if (!line) return emitted;
	const entry = system(line);
	return entry ? [...emitted, entry] : emitted;

/**
 * MARK: logEntryModel
 * @description Pure model for the task Logs tab. Turns a task's structured
 *   log entries (`task.logEntries`, produced by the agent log streamer) into
 *   grouped, filterable, renderable views — and falls back to parsing the
 *   legacy `task.processLogs` text (line-based tag grammar) so old tasks keep
 *   rendering exactly as before.
 *
 *   The tag grammar mirrors the API-side synthesis in
 *   `api/taskStore.js` (_logEntryKindFromText):
 *     [TOOL] [RESULT]      -> kind "tool"      (tools feed)
 *     [THINKING]           -> kind "thinking"  (thinking feed)
 *     [ERROR] [FAIL]       -> kind "error"     (main feed)
 *     [AGENT]              -> kind "assistant" (main feed)
 *     [INFO] [SYSTEM] [GIT] [CI] [CI/CMD] [HUMAN] [WARN] -> kind "system"
 *     untagged text        -> kind "assistant" (main feed)
 */

export const LOG_FEEDS = ['ALL', 'ASSISTANT', 'TOOLS', 'THINKING', 'SYSTEM', 'TELEMETRY', 'RAW'];

const TAG_KIND_RULES = [
  { pattern: /^\[(TOOL|RESULT)\]/, kind: 'tool', feed: 'tools' },
  { pattern: /^\[RUNNER\]/, kind: 'runner', feed: 'main' },
  { pattern: /^\[runner[\] ]/i, kind: 'runner', feed: 'main' },
  { pattern: /^\[THINKING\]/, kind: 'thinking', feed: 'thinking' },
  { pattern: /^\[USAGE\]/, kind: 'telemetry', feed: 'telemetry' },
  { pattern: /^\[RAW\]/, kind: 'raw', feed: 'raw' },
  { pattern: /^\[PERM\]/, kind: 'permission', feed: 'main' },
  { pattern: /^\[PLAN\]/, kind: 'plan', feed: 'main' },
  { pattern: /^\[(ERROR|FAIL|STDERR)\]/, kind: 'error', feed: 'main' },
  {
    pattern: /^\[(INFO|SYSTEM|GIT|CI\/CMD|CI|HUMAN|WARN)\]/,
    kind: 'system',
    feed: 'main',
  },
  { pattern: /^\[AGENT\]/, kind: 'assistant', feed: 'main' },
];

/***
 * MARK: legacyLogEntryId
 * @description Stable synthetic id for a parsed legacy log line.
 ***/
let legacyEntryCounter = 0;
const legacyLogEntryId = () => {
  legacyEntryCounter += 1;
  return `legacy-log-${legacyEntryCounter}`;
};

/***
 * MARK: entryFromLogLine
 * @description Maps one rendered log line to a structured entry using the
 *   shared tag grammar. Untagged text is assistant narrative.
 * @example entryFromLogLine('[TOOL] bash("ls")') => { kind: 'tool', feed: 'tools', text: '…' }
 * @param {string} line
 * @returns {Object} A structured log entry.
 ***/
export function entryFromLogLine(line) {
  const lines = String(line).split('\n');
  const firstLine = lines[0] || '';
  const checkLine = /^\[STDOUT\]/.test(firstLine) && lines.length > 1 ? lines[1] : firstLine;
  const rule = TAG_KIND_RULES.find((r) => r.pattern.test(checkLine));
  const kind = rule ? rule.kind : 'assistant';
  const feed = rule ? rule.feed : 'main';
  return {
    id: legacyLogEntryId(),
    ts: null,
    feed,
    feeds: [feed],
    kind,
    turn: null,
    text: String(line),
    meta: { source: 'legacy-process-logs' },
  };
}

/***
 * MARK: parseLegacyProcessLogs
 * @description Parses the legacy `task.processLogs` text into structured
 *   entries: blank lines are dropped, consecutive duplicates are de-duped
 *   (the exact behavior of today's line-based Logs tab).
 * @example parseLegacyProcessLogs('[INFO] a\n[INFO] a') => [entry('[INFO] a')]
 * @param {string} text
 * @returns {Array<Object>} Structured log entries.
 ***/
export function parseLegacyProcessLogs(text) {
  if (!text || typeof text !== 'string') return [];
  const lines = text.split('\n').filter((l) => l.trim());
  const result = [];
  for (const line of lines) {
    if (result.length === 0 || result.at(-1).text !== line) {
      result.push(entryFromLogLine(line));
    }
  }
  return result;
}

/***
 * MARK: normalizeEntries
 * @description Returns the task's structured log entries when present, or
 *   synthesizes them from the legacy processLogs text otherwise. WebSocket
 *   process lines (live system output) are appended as system entries.
 * @example normalizeEntries(task) => [entry, …]
 * @param {Object} task - The task (may carry logEntries and/or processLogs).
 * @param {Array<Object>} [wsProcessLines] - Live process:stdout lines from the WebSocket.
