function stubClient({ failAfter = Infinity } = {}) {
	const calls = [];
	let sends = 0;
	const client = {
		async logEvents(payload) {
			sends += 1;
			calls.push(payload);
			if (sends > failAfter) {
				const err = new Error("Backend 404 on /log-events");
				err.statusCode = 404;
				throw err;
			}
			return { accepted: true, seq: payload.seq };
		},
	};
	return { client, calls };
